        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-width: 320px;
        background:
          radial-gradient(circle at top left, #293552 0, transparent 36rem),
          radial-gradient(circle at top right, #3a2508 0, transparent 30rem),
          var(--bg);
        color: var(--text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      img,
      svg {
        max-width: 100%;
      }

      a {
        color: inherit;
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--bg), 0 0 0 7px var(--accent-strong);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--accent);
        color: #151004;
        font-weight: 800;
        padding: 0.8rem 1rem;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .site-header,
      main,
      .site-footer {
        width: min(calc(100% - 2rem), var(--max-width));
        margin-inline: auto;
      }

      .site-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.1rem 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        min-width: 0;
        font-size: 1.05rem;
        font-weight: 900;
        letter-spacing: 0.04em;
        text-decoration: none;
        text-transform: uppercase;
      }

      .brand-mark {
        display: grid;
        place-items: center;
        width: 2.6rem;
        height: 2.6rem;
        flex: 0 0 auto;
        border: 1px solid var(--line);
        border-radius: 50%;
        background: linear-gradient(145deg, var(--accent), #b469ff);
        color: #090b10;
        font-weight: 950;
      }

      .primary-nav ul {
        display: flex;
        align-items: center;
        gap: 0.25rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .primary-nav a,
      .ghost-link,
      .button {
        border-radius: 999px;
        font-weight: 800;
        text-decoration: none;
      }

      .primary-nav a,
      .ghost-link {
        display: inline-flex;
        padding: 0.7rem 0.9rem;
        color: var(--muted);
      }

      .primary-nav a:hover,
      .ghost-link:hover {
        background: var(--surface-soft);
        color: var(--text);
      }

      .header-actions {
        display: flex;
        align-items: center;
        gap: 0.5rem;
      }

      .button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        min-height: 2.75rem;
        border: 1px solid transparent;
        background: var(--accent);
        color: #151004;
        padding: 0.75rem 1rem;
        cursor: pointer;
      }

      .button:hover {
        background: var(--accent-strong);
      }

      .button.secondary {
        border-color: var(--line);
        background: var(--surface);
        color: var(--text);
      }

      .button.secondary:hover {
        background: var(--surface-soft);
      }

      main {
        padding-bottom: 4rem;
      }

      section {
        margin-top: 4rem;
      }

      .hero {
        position: relative;
        display: grid;
        grid-template-columns: minmax(0, 1.03fr) minmax(17rem, 0.97fr);
        gap: 1.5rem;
        align-items: stretch;
        margin-top: 1.5rem;
      }

      .hero-copy,
      .hero-card,
      .panel,
      .product-card,
      .deal-card,
      .article-card,
      .newsletter {
        border: 1px solid var(--line);
        box-shadow: var(--shadow);
      }

      .hero-copy {
        display: flex;
        flex-direction: column;
        justify-content: center;
        min-height: 34rem;
        border-radius: var(--radius-lg);
        background:
          linear-gradient(140deg, #151b29 0%, #0e1118 58%, #251905 100%);
        padding: clamp(1.25rem, 5vw, 4rem);
        overflow: hidden;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent-strong);
        font-size: 0.78rem;
        font-weight: 900;
        letter-spacing: 0.16em;
        text-transform: uppercase;
      }

      h1,
      h2,
      h3 {
        margin: 0;
        line-height: 1.02;
        letter-spacing: -0.045em;
      }

      h1 {
        max-width: 11ch;
        font-size: clamp(3rem, 9vw, 6.8rem);
      }

      h2 {
        font-size: clamp(2rem, 5vw, 3.6rem);
      }

      h3 {
        font-size: 1.35rem;
      }

      .hero-copy p {
        max-width: 42rem;
        margin: 1.2rem 0 0;
        color: var(--muted);
        font-size: clamp(1.05rem, 2vw, 1.28rem);
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin-top: 2rem;
      }

      .hero-stats {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.75rem;
        margin-top: 2.5rem;
      }

      .stat {
        min-width: 0;
        border: 1px solid var(--line);
        border-radius: var(--radius-sm);
        background: #0b0f18;
        padding: 1rem;
      }

      .stat strong {
        display: block;
        color: var(--text);
        font-size: 1.4rem;
      }

      .stat span {
        color: var(--muted);
        font-size: 0.9rem;
      }

      .hero-card {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        min-height: 34rem;
        border-radius: var(--radius-lg);
        background:
          linear-gradient(160deg, #202a3d 0%, #0f141f 48%, #422a06 100%);
        padding: 1.25rem;
      }

      .product-visual {
        display: grid;
        place-items: center;
        min-height: 20rem;
        border-radius: 1.4rem;
        background:
          radial-gradient(circle, #ffdd73 0 20%, transparent 21%),
          linear-gradient(140deg, #111722, #2b3448);
      }

      .bag-illustration {
        width: min(17rem, 82%);
        color: var(--accent-strong);
        filter: drop-shadow(0 26px 42px #000000);
      }

      .hero-card-footer {
        display: grid;
        gap: 1rem;
        padding: 1.25rem 0.25rem 0;
      }

      .price-line {
        display: flex;
        align-items: baseline;
        justify-content: space-between;
        gap: 1rem;
      }

      .price-line strong {
        font-size: 2rem;
      }

      .rating {
        color: var(--accent-strong);
        font-weight: 900;
      }

      .section-heading {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.25rem;
      }

      .section-heading p {
        max-width: 38rem;
        margin: 0.6rem 0 0;
        color: var(--muted);
      }

      .product-grid {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 1rem;
      }

      .product-card,
      .deal-card,
      .article-card,
      .newsletter,
      .panel {
        border-radius: var(--radius-md);
        background: linear-gradient(180deg, var(--surface-strong), var(--surface));
      }

      .product-card {
        display: grid;
        gap: 1rem;
        padding: 1rem;
      }

      .product-card .thumb {
        display: grid;
        place-items: center;
        min-height: 12rem;
        border-radius: var(--radius-sm);
        background: var(--surface-soft);
      }

      .thumb svg {
        width: 7rem;
        color: var(--accent-strong);
      }

      .product-meta {
        display: grid;
        gap: 0.45rem;
      }

      .tag-row {
        display: flex;
        flex-wrap: wrap;
        gap: 0.5rem;
      }

      .tag {
        border: 1px solid var(--line);
        border-radius: 999px;
        color: var(--muted);
        font-size: 0.78rem;
        font-weight: 800;
        padding: 0.3rem 0.55rem;
      }

      .product-card p,
      .deal-card p,
      .article-card p {
        margin: 0;
        color: var(--muted);
      }

      .card-price {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        font-weight: 900;
      }

      .deals-layout {
        display: grid;
        grid-template-columns: 1.2fr 0.8fr;
        gap: 1rem;
      }

      .deal-card {
        min-width: 0;
        padding: clamp(1rem, 3vw, 2rem);
      }

      .deal-card.feature {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(12rem, 0.62fr);
        gap: 1rem;
        align-items: center;
        background:
          linear-gradient(130deg, #2c1f08 0%, #182131 54%, #111722 100%);
      }

      .deal-stack {
        display: grid;
        gap: 1rem;
      }

      .deal-value {
        display: inline-flex;
        width: fit-content;
        margin: 1rem 0;
        border-radius: 999px;
        background: var(--accent);
        color: #151004;
        font-size: clamp(1.35rem, 4vw, 2.4rem);
        font-weight: 950;
        letter-spacing: -0.04em;
        padding: 0.35rem 0.8rem;
      }

      .countdown {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.6rem;
        margin-top: 1.25rem;
      }

      .countdown span {
        display: grid;
        place-items: center;
        border: 1px solid var(--line);
        border-radius: var(--radius-sm);
        background: #0b0f18;
        padding: 0.8rem 0.4rem;
        color: var(--muted);
        text-align: center;
      }

      .countdown strong {
        display: block;
        color: var(--text);
        font-size: 1.3rem;
      }

      .editorial-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr 0.9fr;
        gap: 1rem;
      }

      .article-card {
        min-width: 0;
        overflow: hidden;
      }

      .article-card.featured {
        grid-row: span 2;
      }

      .article-media {
        min-height: 13rem;
        background:
          linear-gradient(135deg, #343f59, transparent),
          repeating-linear-gradient(
            -35deg,
            #1f2a3f 0 14px,
            #141b29 14px 28px
          );
      }

      .article-card.featured .article-media {
        min-height: 20rem;
      }

      .article-body {
        display: grid;
        gap: 0.75rem;
        padding: 1.25rem;
      }

      .newsletter {
        display: grid;
        grid-template-columns: minmax(0, 0.92fr) minmax(16rem, 1.08fr);
        gap: 1.5rem;
        align-items: center;
        padding: clamp(1.25rem, 4vw, 2.5rem);
      }

      .newsletter p {
        color: var(--muted);
      }

      .email-form {
        display: flex;
        gap: 0.75rem;
        align-items: end;
      }

      .field {
        display: grid;
        flex: 1 1 auto;
        gap: 0.45rem;
        min-width: 0;
      }

      label {
        color: var(--text);
        font-weight: 850;
      }

      input {
        width: 100%;
        min-height: 2.9rem;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: #090d15;
        color: var(--text);
        font: inherit;
        padding: 0.75rem 1rem;
      }

      .help-text,
      .form-status {
        margin: 0;
        color: var(--muted);
        font-size: 0.9rem;
      }

      .site-footer {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        border-top: 1px solid var(--line);
        color: var(--muted);
        padding: 2rem 0;
      }

      @media (max-width: 940px) {
        .site-header,
        .header-actions,
        .primary-nav ul {
          flex-wrap: wrap;
        }

        .hero,
        .deals-layout,
        .deal-card.feature,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .product-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .editorial-grid {
          grid-template-columns: 1fr 1fr;
        }
      }

      @media (max-width: 620px) {
        .site-header,
        .site-footer,
        .email-form,
        .section-heading {
          align-items: stretch;
          flex-direction: column;
        }

        .primary-nav a {
          padding-inline: 0.72rem;
        }

        .hero-copy,
        .hero-card {
          min-height: auto;
        }

        .hero-stats,
        .countdown,
        .product-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .article-card.featured {
          grid-row: auto;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        body,
        .hero-copy,
        .hero-card,
        .panel,
        .product-card,
        .deal-card,
        .article-card,
        .newsletter,
        .stat,
        .countdown span,
        input {
          background: Canvas;
          color: CanvasText;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .button,
        .skip-link,
        .deal-value {
          background: ButtonFace;
          color: ButtonText;
          border-color: ButtonBorder;
        }

        a:focus-visible,
        button:focus-visible,
        input:focus-visible {
          outline: 3px solid ButtonText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>
    <noscript>
      <main class="site-header">
        <h1>Nocturne Supply Co.</h1>
        <p>This ecommerce home page needs JavaScript enabled to render the product sections.</p>
      </main>
    </noscript>

    <script>
      const products = [
        {
          name: "Apex Commuter Tote",
          description: "Weather-ready carryall with recycled canvas and brass hardware.",
          price: "$148",
          tag: "Bestseller",
          icon: "bag"
        },
        {
          name: "Midnight Runner",
          description: "Responsive knit sneaker designed for city miles after dark.",
          price: "$132",
          tag: "New color",
          icon: "shoe"
        },
        {
          name: "Luma Desk Lamp",
          description: "Dimmable task light with a sculptural matte graphite finish.",
          price: "$96",
          tag: "Home edit",
          icon: "lamp"
        },
        {
          name: "Signal Field Jacket",
          description: "Layered shell with thermal lining and concealed travel pockets.",
          price: "$224",
          tag: "Limited run",
          icon: "jacket"
        }
      ];

      const deals = [
        {
          title: "Weekend capsule bundle",
          body: "Save when you pair travel-ready apparel, accessories, and home essentials.",
          value: "Up to 35% off",
          cta: "Shop weekend deals"
        },
        {
          title: "Member early access",
          body: "Loyalty members unlock the spring preview before public release.",
          value: "48-hour head start",
          cta: "Join free"
        }
      ];

      const articles = [
        {
          title: "The dark neutrals buying guide",
          body: "Build a wardrobe foundation with layered textures, durable finishes, and sharp silhouettes.",
          category: "Style notes",
          featured: true
        },
        {
          title: "Five upgrades for a calmer workspace",
          body: "Editorial picks for lighting, storage, and tactile desk objects.",
          category: "Home"
        },
        {
          title: "How our repair program works",
          body: "Keep favorite pieces in rotation with in-house mending and care kits.",
          category: "Circular design"
        },
        {
          title: "Inside the May lookbook",
          body: "See the season's tonal styling story from our latest studio shoot.",
          category: "Lookbook"
        }
      ];

      const iconPaths = {
        bag: '<path d="M26 25h44l-4 42H30L26 25Z"/><path d="M38 25a10 10 0 0 1 20 0"/><path d="M38 39h.01M58 39h.01"/>',
        shoe: '<path d="M18 55c15 5 36 6 52 2 4-1 6-6 2-9l-11-8c-8 7-21 9-31 2l-6-4-6 17Z"/><path d="M35 45l8-8M45 47l8-8"/>',
        lamp: '<path d="M36 18h28l7 25H29l7-25Z"/><path d="M50 43v25M36 68h28"/><path d="M50 18V9"/>',
        jacket: '<path d="M30 22 18 33v35h19V45h26v23h19V33L70 22l-10-7c-5 8-15 8-20 0l-10 7Z"/><path d="M40 15v30M60 15v30"/>'
      };

      const Icon = (name, label) => `
        <svg viewBox="0 0 100 100" role="img" aria-label="${label}" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round">
          ${iconPaths[name]}
        </svg>
      `;

      const Header = () => `
        <header class="site-header">
          <a class="brand" href="#" aria-label="Nocturne Supply Co. home">
            <span class="brand-mark" aria-hidden="true">N</span>
            <span>Nocturne Supply</span>
          </a>
          <nav class="primary-nav" aria-label="Primary navigation">
            <ul>
              <li><a href="#featured">Featured</a></li>
              <li><a href="#deals">Deals</a></li>
              <li><a href="#editorial">Editorial</a></li>
              <li><a href="#newsletter">Members</a></li>
            </ul>
          </nav>
          <div class="header-actions">
            <a class="ghost-link" href="#editorial">Stories</a>
            <a class="button" href="#featured" aria-label="Shop new arrivals">Shop new arrivals</a>
          </div>
        </header>
      `;

      const Hero = () => `
        <section class="hero" aria-labelledby="hero-title">
          <div class="hero-copy">
            <p class="eyebrow">Seasonal drop 05</p>
            <h1 id="hero-title">Retail for after hours.</h1>
            <p>
              Discover elevated apparel, home goods, and carry essentials designed
              in a refined dark palette for every part of the day.
            </p>
            <div class="hero-actions">
              <a class="button" href="#featured">Shop featured products</a>
              <a class="button secondary" href="#deals">View current deals</a>
            </div>
            <div class="hero-stats" aria-label="Store highlights">
              <div class="stat"><strong>4.8/5</strong><span>Average customer rating</span></div>
              <div class="stat"><strong>24h</strong><span>Fast dispatch on essentials</span></div>
              <div class="stat"><strong>85%</strong><span>Lower-impact materials this drop</span></div>
            </div>
          </div>
          <article class="hero-card" aria-labelledby="spotlight-title">
            <div class="product-visual">
              <div class="bag-illustration">${Icon("bag", "A structured tote bag illustration")}</div>
            </div>
            <div class="hero-card-footer">
              <p class="eyebrow">Product spotlight</p>
              <div class="price-line">
                <h2 id="spotlight-title">Apex Commuter Tote</h2>
                <strong>$148</strong>
              </div>
              <p class="rating" aria-label="Rated 4.9 out of 5 stars">★★★★★ 4.9</p>
              <a class="button" href="#featured">Explore the tote</a>
            </div>
          </article>
        </section>
      `;

      const ProductCard = (product) => `
        <article class="product-card">
          <div class="thumb">${Icon(product.icon, `${product.name} product illustration`)}</div>
          <div class="product-meta">
            <div class="tag-row"><span class="tag">${product.tag}</span></div>
            <h3>${product.name}</h3>
            <p>${product.description}</p>
          </div>
          <div class="card-price">
            <span>${product.price}</span>
            <a class="button secondary" href="#" aria-label="Add ${product.name} to cart">Add to cart</a>
          </div>
        </article>
      `;

      const FeaturedProducts = () => `
        <section id="featured" aria-labelledby="featured-title">
          <div class="section-heading">
            <div>
              <p class="eyebrow">Featured products</p>
              <h2 id="featured-title">Built for daily rituals.</h2>
              <p>Our merchandising team selected these high-demand pieces for quality, utility, and a polished monochrome finish.</p>
            </div>
            <a class="ghost-link" href="#">View all products</a>
          </div>
          <div class="product-grid">
            ${products.map(ProductCard).join("")}
          </div>
        </section>
      `;

      const Deals = () => `
        <section id="deals" aria-labelledby="deals-title">
          <div class="section-heading">
            <div>
              <p class="eyebrow">Limited-time deals</p>
              <h2 id="deals-title">Sharp offers, no clutter.</h2>
              <p>Short-run bundles and member perks designed to help you complete the set.</p>
            </div>
          </div>
          <div class="deals-layout">
            <article class="deal-card feature" aria-labelledby="deal-main-title">
              <div>
                <p class="eyebrow">Ends Sunday</p>
                <h3 id="deal-main-title">${deals[0].title}</h3>
                <span class="deal-value">${deals[0].value}</span>
                <p>${deals[0].body}</p>
                <div class="countdown" aria-label="Deal countdown">
                  <span><strong>02</strong>days</span>
                  <span><strong>14</strong>hours</span>
                  <span><strong>36</strong>minutes</span>
                </div>
              </div>
              <a class="button" href="#" aria-label="${deals[0].cta}">${deals[0].cta}</a>
            </article>
            <div class="deal-stack">
              <article class="deal-card">
                <p class="eyebrow">Members</p>
                <h3>${deals[1].title}</h3>
                <span class="deal-value">${deals[1].value}</span>
                <p>${deals[1].body}</p>
                <p><a class="ghost-link" href="#newsletter">${deals[1].cta}</a></p>
              </article>
              <article class="deal-card">
                <p class="eyebrow">Free shipping</p>
                <h3>Complimentary delivery over $95</h3>
                <p>Standard carbon-conscious shipping is included on qualifying orders.</p>
              </article>
            </div>
          </div>
        </section>
      `;

      const ArticleCard = (article) => `
        <article class="article-card ${article.featured ? "featured" : ""}">
          <div class="article-media" aria-hidden="true"></div>
          <div class="article-body">
            <p class="eyebrow">${article.category}</p>
            <h3>${article.title}</h3>
            <p>${article.body}</p>
            <a class="ghost-link" href="#" aria-label="Read article: ${article.title}">Read article</a>
          </div>
        </article>
      `;

      const Editorial = () => `
        <section id="editorial" aria-labelledby="editorial-title">
          <div class="section-heading">
            <div>
