                <p class="eyebrow">Free shipping</p>
                <h3>Complimentary delivery over $95</h3>
                <p>Standard carbon-conscious shipping is included on qualifying orders.</p>
              </article>
            </div>
          </div>
        </section>
      `;

      const ArticleCard = (article) => `
