        </section>
      `;

      const Newsletter = () => `
        <section id="newsletter" class="newsletter" aria-labelledby="newsletter-title">
          <div>
            <p class="eyebrow">Private list</p>
            <h2 id="newsletter-title">Get first pick of the next drop.</h2>
            <p>Join for launch alerts, members-only deals, and editorial product guides.</p>
